                cart.forEach((item, index) => {
                    const itemTotal = item.preco;
                    total += itemTotal;

                    // Cria o elemento HTML para cada item
                    const itemDiv = document.createElement('div');
                    itemDiv.style.padding = '10px 0';
                    itemDiv.style.borderBottom = '1px dotted #eee';
